'use strict';
const dialog = document.querySelector('#panel');
const body = document.querySelector('#panel-body');
const audioButton = document.querySelector('#audio');
let audioContext, drone, droneGain, dialogOpener, whisperTimer;
let prefs = { sound: false, volume: .25, motion: !matchMedia('(prefers-reduced-motion: reduce)').matches };
try { const saved = JSON.parse(localStorage.getItem('clue-menu-preferences') || '{}'); if (typeof saved.motion === 'boolean') prefs.motion = saved.motion; if (typeof saved.volume === 'number') prefs.volume = Math.min(1, Math.max(0, saved.volume)); } catch {}
function savePrefs() { try { localStorage.setItem('clue-menu-preferences', JSON.stringify({ volume: prefs.volume, motion: prefs.motion })); } catch {} }
function applyPrefs() { document.documentElement.classList.toggle('no-motion', !prefs.motion); audioButton.setAttribute('aria-pressed', String(prefs.sound)); audioButton.setAttribute('aria-label', prefs.sound ? '关闭环境音' : '开启环境音'); audioButton.innerHTML = `♪ <span>声音${prefs.sound ? '开' : '关'}</span>`; if (droneGain && audioContext) droneGain.gain.setTargetAtTime(prefs.sound ? prefs.volume * .045 : 0, audioContext.currentTime, .2); savePrefs(); }
async function toggleSound() { try { if (!audioContext) { const Audio = window.AudioContext || window.webkitAudioContext; if (!Audio) throw new Error('unsupported'); audioContext = new Audio(); drone = audioContext.createOscillator(); droneGain = audioContext.createGain(); drone.frequency.value = 64; droneGain.gain.value = 0; drone.connect(droneGain).connect(audioContext.destination); drone.start(); } await audioContext.resume(); prefs.sound = !prefs.sound; applyPrefs(); } catch { announce('当前浏览器暂时无法播放环境音。'); } }
function announce(text) { clearTimeout(whisperTimer); const el = document.querySelector('#scene-message') || document.querySelector('#whisper'); el.textContent = text; el.classList.add('active'); whisperTimer = setTimeout(() => { el.textContent = el.id === 'scene-message' ? '门内安静了下来。' : '每一个故事，都有尚未问出口的问题。'; el.classList.remove('active'); }, 4200); }
function knock() { announce('笃、笃、笃。没有人回应。'); if (!prefs.sound || !audioContext) return; for (let i = 0; i < 3; i++) { const o = audioContext.createOscillator(), g = audioContext.createGain(), t = audioContext.currentTime + i * .23; o.frequency.setValueAtTime(145, t); o.frequency.exponentialRampToValueAtTime(55, t + .1); g.gain.setValueAtTime(.001, t); g.gain.linearRampToValueAtTime(prefs.volume * .4, t + .006); g.gain.exponentialRampToValueAtTime(.001, t + .16); o.connect(g).connect(audioContext.destination); o.start(t); o.stop(t + .18); o.onended = () => {o.disconnect(); g.disconnect();}; } }
const screens = {
  chapters: () => `<p class="panel-kicker">STORY COLLECTION</p><h2 id="panel-title">选择一个未解的故事</h2><button class="chapter-choice" data-open="case"><img src="./assets/apartment-menu.png" alt="402号房门"/><span><small>第一章 · 3D 场景调查</small><h3>蓝血</h3><small>旧公寓 / 五问推理</small></span><span class="arrow">↗</span></button><p class="coming">其他故事尚在筛选中。<br>每个关卡都将保留可查阅的知乎原文来源。</p>`,
  case: () => `<p class="panel-kicker">CASE 001 / 第一章</p><h2 id="panel-title">蓝血</h2><img class="case-image" src="./assets/apartment-menu.png" alt="深夜公寓里透出暖光的402号房门"/><div class="panel-copy"><p>昨晚的急救演示结束后，房间里留下了一抹不该出现的蓝色。三个人都说自己只看见了其中一部分。</p><p>你可以先写下五个解释，再通过道具、日记和对话，把“蓝血是什么”问到关键处。</p></div><div class="case-facts"><span>场景调查</span><span>人物追问</span><span>五问结案</span></div><div class="notice">整合版已开放：阅读日记、查看关键物件、询问三名在场者，最后提交五题解释。蓝血故事母题来自知乎官方黑客松内容，房间与结局为新增改编。</div><div class="panel-actions"><a class="primary" href="./room.html"><span>进入调查现场</span><span>↗</span></a><button class="back-button" data-open="prologue"><span>阅读序幕</span><span>↗</span></button><button class="back-button" data-open="chapters">返回故事列表</button></div>`,
  prologue: () => `<p class="panel-kicker">序幕 / 旧公寓 · 深夜</p><h2 id="panel-title">这次，换你敲门。</h2><div class="panel-copy"><p>钥匙在掌心里留下了一道浅浅的印子。你刚走到四楼，身后的脚步声就停了。</p><p>门卫站在楼梯口，没有跟过来。</p></div><blockquote class="prologue-quote">“普通东西随便收拾。<br>那些杂物，交给我就好。”</blockquote><div class="panel-copy"><p>你还没问清楚他说的是哪些杂物，门后忽然响了三下。</p><p>笃。笃。笃。</p><p>可他刚刚才告诉你，这里已经很久没有人住了。</p></div><div class="notice">序幕为游戏改编文本。现在可以进入房间，体验移动、物品调查与演示对话。</div><a class="primary" href="./room.html"><span>推门进入 · 3D 试玩</span><span>↗</span></a><button class="back-button" data-open="case">返回案件简介</button>`,
  guide: () => `<p class="panel-kicker">INVESTIGATOR'S NOTES</p><h2 id="panel-title">先写下你的解释</h2><div class="steps"><div class="step"><div><strong>先留下五个判断</strong><p>蓝血是什么、从哪里来、昨晚发生什么、谁在撒谎、为什么撒谎。答案可以之后反复修改。</p></div></div><div class="step"><div><strong>再看现场</strong><p>道具有关键证据，也有普通生活物件和故意相似的干扰项。不是每件东西都要提供线索。</p></div></div><div class="step"><div><strong>最后对照说法</strong><p>角色只知道自己经历的一部分。记不清、看错和刻意隐瞒，是不同的事情。</p></div></div></div><div class="notice">第一幕整合版包含日记、道具调查、人物问答和五题结案。</div>`,
  sources: () => `<p class="panel-kicker">FROM ZHIHU</p><h2 id="panel-title">故事有来处，推理有依据</h2><div class="panel-copy"><p>《蓝血》的核心母题来自知乎黑客松官方故事内容：急救培训中，主角发现自己与周围人对“血液颜色”的认知不同，并察觉有人在观察自己。</p><p><a href="https://api.zhihu.com/km-indep-home/hackathon/v2/story/2025684191967294692" target="_blank" rel="noopener noreferrer">查看知乎官方故事来源 ↗</a></p><p>本关保留上述母题，蓝血的具体来源、昨晚经过、撒谎者和动机属于新增游戏改编，不冒充原文结局。</p></div><div class="notice">原始故事可能包含剧透。使用和改编范围仍需按比赛规则确认；本页面为独立参赛作品原型，不代表知乎官方发布。</div>`,
  settings: () => `<p class="panel-kicker">PREFERENCES</p><h2 id="panel-title">按你的节奏进入故事</h2><label class="setting-row"><span>环境声音<small>开启后播放低声氛围音与敲门声</small></span><input id="sound-setting" type="checkbox" ${prefs.sound ? 'checked' : ''}/></label><label class="setting-row"><span>音量<small>建议佩戴耳机，保持适中音量</small></span><input id="volume-setting" type="range" min="0" max="100" value="${Math.round(prefs.volume * 100)}" aria-label="环境音量"/></label><label class="setting-row"><span>界面动态<small>关闭后减少入场与过渡动画</small></span><input id="motion-setting" type="checkbox" ${prefs.motion ? 'checked' : ''}/></label><p class="notice">偏好仅保存在当前浏览器。每次打开页面时，声音默认关闭。</p>`
};
const prologueText = screens.prologue;
screens.prologue = () => prologueText().replace('<div class="panel-copy">', '<img class="case-image prologue-art" src="./assets/apartment-menu.png" alt="第一幕：402号公寓门前"/><div class="panel-copy">') + '<div class="panel-actions"><button class="back-button" id="chapter-knock">轻敲房门</button><span class="scene-feedback" id="scene-message" role="status">试着听听门后的回应。</span></div>';
function openPanel(name) { if (!screens[name]) return; if (!dialog.open) dialogOpener = document.activeElement; document.body.classList.toggle('chapter-one', name === 'case' || name === 'prologue'); body.innerHTML = screens[name](); document.querySelector('#panel-kind').textContent = name === 'settings' ? '设置' : name === 'sources' ? '来源' : '01'; if (!dialog.open) dialog.showModal(); dialog.scrollTop = 0; document.querySelector('#close-panel').focus(); body.querySelector('#chapter-knock')?.addEventListener('click', knock); body.querySelector('#sound-setting')?.addEventListener('change', async e => { await toggleSound(); e.target.checked = prefs.sound; }); body.querySelector('#volume-setting')?.addEventListener('input', e => { prefs.volume = Number(e.target.value) / 100; applyPrefs(); }); body.querySelector('#motion-setting')?.addEventListener('change', e => { prefs.motion = e.target.checked; applyPrefs(); }); }
document.addEventListener('click', e => { const target = e.target.closest('[data-open]'); if (target) openPanel(target.dataset.open); });
document.querySelector('#close-panel').addEventListener('click', () => dialog.close());
dialog.addEventListener('click', e => { if (e.target === dialog) { const r = dialog.getBoundingClientRect(); if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) dialog.close(); } });
dialog.addEventListener('close', () => { document.body.classList.remove('chapter-one'); clearTimeout(whisperTimer); dialogOpener?.focus(); });
document.querySelector('#settings').addEventListener('click', () => openPanel('settings'));
audioButton.addEventListener('click', toggleSound);
document.addEventListener('visibilitychange', () => { if (!audioContext) return; if (document.hidden) audioContext.suspend().catch(() => {}); else if (prefs.sound) audioContext.resume().catch(() => {}); });
applyPrefs();
